// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.cognitive.model/** * NOUS — Cognitive Configuration (Module 7 v2 — Step 7.1). * * Configuration for all cognitive engines. All values are tunable per * persona (via [com.roshan.persona.persona.core.LlmHyperparams]) and * globally (via this config). * * ## Performance budgets (per strategy v2 §"Performance Budgets") * *  - Task decomposition: < 3s *  - Chain-of-thought: < 5s (3-5 steps) *  - Self-correction: < 15s (max 3 attempts) *  - Decision making: < 5s *  - Full pipeline: < 25s (with clarification Q&A) *  - Cache hit: < 200ms * * @see <a href="docs/strategy/module-7-cognitive-strategy-v2.md">§Performance Budgets</a> */data class CognitiveConfig(    // ─── Clarification ──────────────────────────────────────────────────────    /** Max clarifying questions before planning (default 2 — don't annoy user). */    val maxClarificationQuestions: Int = DEFAULT_MAX_CLARIFICATION,    // ─── Task Planner ───────────────────────────────────────────────────────    /** Min sub-tasks per decomposition (default 3 — meaningful decomposition). */    val minSubTasks: Int = DEFAULT_MIN_SUB_TASKS,    /** Max sub-tasks per decomposition (default 7 — avoid over-planning). */    val maxSubTasks: Int = DEFAULT_MAX_SUB_TASKS,    /** Max plan execution time before timeout (ms). */    val planExecutionTimeoutMs: Long = DEFAULT_PLAN_TIMEOUT,    // ─── Reasoning Engine ───────────────────────────────────────────────────    /** Min reasoning steps in chain-of-thought (default 3). */    val minReasoningSteps: Int = DEFAULT_MIN_REASONING_STEPS,    /** Max reasoning steps in chain-of-thought (default 10 — avoid endless). */    val maxReasoningSteps: Int = DEFAULT_MAX_REASONING_STEPS,    /** Max self-correction attempts (default 3 per strategy Q3). */    val maxCorrectionAttempts: Int = DEFAULT_MAX_CORRECTIONS,    // ─── Decision Maker ─────────────────────────────────────────────────────    /** Min decision options (default 2 — need at least 2 to compare). */    val minDecisionOptions: Int = DEFAULT_MIN_DECISION_OPTIONS,    /** Max decision options (default 5 — avoid decision paralysis). */    val maxDecisionOptions: Int = DEFAULT_MAX_DECISION_OPTIONS,    // ─── Confidence Thresholds ──────────────────────────────────────────────    /** Confidence ≥ this → assertive recommendation (default 0.9). */    val confidenceAssertiveThreshold: Float = DEFAULT_CONFIDENCE_ASSERTIVE,    /** Confidence ≥ this → cautious recommendation (default 0.7). */    val confidenceCautiousThreshold: Float = DEFAULT_CONFIDENCE_CAUTIOUS,    /** Confidence < this → defer / ask follow-up (default 0.3). */    val confidenceDeferThreshold: Float = DEFAULT_CONFIDENCE_DEFER,    // ─── Reasoning Cache ────────────────────────────────────────────────────    /** Cache TTL in days (default 7 — per strategy v2). */    val cacheTtlDays: Int = DEFAULT_CACHE_TTL_DAYS,    /** Max cached traces (default 100 — LRU eviction). */    val maxCachedTraces: Int = DEFAULT_MAX_CACHED_TRACES,    // ─── Reasoning Trace Storage ────────────────────────────────────────────    /** Trace storage TTL in days (default 30 — per strategy Q7). */    val traceStorageTtlDays: Int = DEFAULT_TRACE_TTL_DAYS,    /** Max stored traces (default 500 — LRU eviction). */    val maxStoredTraces: Int = DEFAULT_MAX_STORED_TRACES,    // ─── Replanning ─────────────────────────────────────────────────────────    /** Max replan attempts per sub-task failure (default 2). */    val maxReplanAttempts: Int = DEFAULT_MAX_REPLAN,) {    init {        require(maxClarificationQuestions in 0..5) { "maxClarificationQuestions must be 0..5" }        require(minSubTasks in 1..20) { "minSubTasks must be 1..20" }        require(maxSubTasks in minSubTasks..20) { "maxSubTasks must be >= minSubTasks and <= 20" }        require(planExecutionTimeoutMs > 0) { "planExecutionTimeoutMs must be positive" }        require(minReasoningSteps in 1..20) { "minReasoningSteps must be 1..20" }        require(maxReasoningSteps in minReasoningSteps..30) { "maxReasoningSteps must be >= min" }        require(maxCorrectionAttempts in 1..5) { "maxCorrectionAttempts must be 1..5" }        require(minDecisionOptions in 2..10) { "minDecisionOptions must be 2..10" }        require(maxDecisionOptions in minDecisionOptions..10) { "maxDecisionOptions must be >= min" }        require(confidenceAssertiveThreshold in 0f..1f) { "confidenceAssertiveThreshold must be [0,1]" }        require(confidenceCautiousThreshold in 0f..confidenceAssertiveThreshold) {            "confidenceCautiousThreshold must be <= assertive"        }        require(confidenceDeferThreshold in 0f..confidenceCautiousThreshold) {            "confidenceDeferThreshold must be <= cautious"        }        require(cacheTtlDays > 0) { "cacheTtlDays must be positive" }        require(maxCachedTraces > 0) { "maxCachedTraces must be positive" }        require(traceStorageTtlDays > 0) { "traceStorageTtlDays must be positive" }        require(maxStoredTraces > 0) { "maxStoredTraces must be positive" }        require(maxReplanAttempts in 0..5) { "maxReplanAttempts must be 0..5" }    }    companion object {        const val DEFAULT_MAX_CLARIFICATION = 2        const val DEFAULT_MIN_SUB_TASKS = 3        const val DEFAULT_MAX_SUB_TASKS = 7        const val DEFAULT_PLAN_TIMEOUT = 60_000L  // 60s        const val DEFAULT_MIN_REASONING_STEPS = 3        const val DEFAULT_MAX_REASONING_STEPS = 10        const val DEFAULT_MAX_CORRECTIONS = 3        const val DEFAULT_MIN_DECISION_OPTIONS = 2        const val DEFAULT_MAX_DECISION_OPTIONS = 5        const val DEFAULT_CONFIDENCE_ASSERTIVE = 0.9f        const val DEFAULT_CONFIDENCE_CAUTIOUS = 0.7f        /** Strategy §8: confidence < 0.6 → DEFER/ADMIT/ASK. Was 0.3 — audit fix. */        const val DEFAULT_CONFIDENCE_DEFER = 0.6f        /** Strategy §8: "cache check (reasoning cache, TTL 24h)". Was 7 days — audit fix. */        const val DEFAULT_CACHE_TTL_DAYS = 1        const val DEFAULT_MAX_CACHED_TRACES = 100        const val DEFAULT_TRACE_TTL_DAYS = 30        const val DEFAULT_MAX_STORED_TRACES = 500        const val DEFAULT_MAX_REPLAN = 2    }}